CREATE TABLE IF NOT EXISTS admin (id INTEGER PRIMARY KEY CHECK(id=1), salt TEXT NOT NULL, hash TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1), registration INTEGER NOT NULL DEFAULT 1, token_hash TEXT, token_updated INTEGER);
INSERT OR IGNORE INTO settings(id) VALUES(1);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, csrf TEXT NOT NULL, version INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS nodes (id TEXT PRIMARY KEY, ip TEXT NOT NULL, name TEXT NOT NULL, origin TEXT NOT NULL, key_hash TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, registered INTEGER NOT NULL, last_seen INTEGER, last_request INTEGER);
CREATE TABLE IF NOT EXISTS attempts (key TEXT NOT NULL, bucket INTEGER NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(key,bucket));
